import React, { useState } from "react";
import { addNotice, addStudy } from "../../services/api";

const AdminDashboard = () => {

  // 📢 NOTICE STATE
  const [noticeTitle, setNoticeTitle] = useState("");
  const [noticeContent, setNoticeContent] = useState("");

  // 📚 STUDY STATE
  const [studyTitle, setStudyTitle] = useState("");
  const [studySubject, setStudySubject] = useState("");
  const [studyContent, setStudyContent] = useState("");

  // ✅ ADD NOTICE (YOUR FUNCTION - CORRECT)
  const handleAddNotice = async () => {
    try {
      const res = await addNotice({
        title: noticeTitle,
        content: noticeContent
      });

      alert(res.data.message);

      // clear input
      setNoticeTitle("");
      setNoticeContent("");

    } catch (err) {
      console.error(err);
      alert("Error adding notice");
    }
  };

  // ✅ ADD STUDY
  const handleAddStudy = async () => {
    try {
      const res = await addStudy({
        title: studyTitle,
        subject: studySubject,
        content: studyContent
      });

      alert(res.data.message);

      setStudyTitle("");
      setStudySubject("");
      setStudyContent("");

    } catch (err) {
      console.error(err);
      alert("Error adding study");
    }
  };

  return (
    <div style={styles.container}>

      <h1>Admin Dashboard</h1>

      {/* 📢 NOTICE */}
      <div style={styles.card}>
        <h2>Add Notice</h2>

        <input
          style={styles.input}
          placeholder="Title"
          value={noticeTitle}
          onChange={(e) => setNoticeTitle(e.target.value)}
        />

        <input
          style={styles.input}
          placeholder="Content"
          value={noticeContent}
          onChange={(e) => setNoticeContent(e.target.value)}
        />

        {/* ✅ BUTTON CONNECTED */}
        <button style={styles.button} onClick={handleAddNotice}>
          Add Notice
        </button>
      </div>

      {/* 📚 STUDY */}
      <div style={styles.card}>
        <h2>Add Study</h2>

        <input
          style={styles.input}
          placeholder="Title"
          value={studyTitle}
          onChange={(e) => setStudyTitle(e.target.value)}
        />

        <input
          style={styles.input}
          placeholder="Subject"
          value={studySubject}
          onChange={(e) => setStudySubject(e.target.value)}
        />

        <input
          style={styles.input}
          placeholder="Content"
          value={studyContent}
          onChange={(e) => setStudyContent(e.target.value)}
        />

        <button style={styles.button} onClick={handleAddStudy}>
          Add Study
        </button>
      </div>

    </div>
  );
};

export default AdminDashboard;


// 🎨 STYLE
const styles = {
  container: {
    padding: "30px",
    background: "#0f172a",
    minHeight: "100vh",
    color: "white",
  },
  card: {
    background: "#1e293b",
    padding: "20px",
    borderRadius: "10px",
    marginBottom: "20px",
    maxWidth: "400px",
  },
  input: {
    width: "100%",
    padding: "10px",
    margin: "10px 0",
    borderRadius: "6px",
    border: "none",
    background: "#334155",
    color: "white",
  },
  button: {
    padding: "10px",
    background: "#38bdf8",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
    fontWeight: "bold",
  },
};
